// 使用DFS统计徒弟和徒弟的徒弟中排名排名高的数量
// src 源头id  current 当前考虑的id 
int DFS(int src, int currnet, set<int>& hight, map<int, set<int>>& mp) {
    // 不可能存在比排名为1实力强的徒弟了
    if (src == 1) {
        return 0;
    }
    for (int sequence : mp[currnet]) {
        // 成环了,数据有问题
        if (sequence == src) {
            return -1;
        }
        // 是否已经遍历过了
        bool flag = true;
        if (sequence < src) {
            if (hight.find(sequence) == hight.end()) {
                hight.insert(sequence);
            } else {
                flag = false;
            }
        }
        if (flag) {
            int res = DFS(src, sequence, hight, mp);
            if (res == -1) {
                return -1;
            }
        }
    }
    return hight.size();
}
