        tmp.pop_back();
        vector<string> tmpArr = split(tmp, ",");
        int parent = stoi(tmpArr[0]);
        int children = stoi(tmpArr[1]);
        if (mp.find(parent) == mp.end()) {
            mp[parent] = set<int>();
        }
        if (mp.find(children) == mp.end()) {
            mp[children] = set<int>();
        }        
        mp[parent].insert(children);
    }
    // 递归计算比自己排名靠前的
​
    vector<pair<int, int>> ans;
    for (auto p : mp) {
        int src = p.first;
        set<int> s;
        int count = DFS(src, src, s, mp);
        // 出现成环的情况 不是意料之中的情况
        if (count == -1) {
            cout << -1;
            return 0;
        }
        ans.push_back({src, count});
    }
    // 按照第一个值进行升序排序
    sort(ans.begin(), ans.end());
    string res = "[";
    for (int i = 0; i < ans.size(); i++) {
        res += to_string(ans[i].second) + ",";
    }
    res.pop_back();
