package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
    "sort"
)
​
// 使用 DFS 统计徒弟和徒弟的徒弟中排名高的数量
func dfs(src, current int, higher map[int]bool, mp map[int]map[int]bool) int {
    //  不可能存在比排名为1实力强的徒弟了
    if src == 1 {
        return 0
    }
    for sequence := range mp[current] {
        // 成环了，数据有问题
        if sequence == src {
            return -1
        }
        flag := true
        if sequence < src {
            if !higher[sequence] {
                higher[sequence] = true
            } else {
                flag = false
            }
        }
        if flag {
            if res := dfs(src, sequence, higher, mp); res == -1 {
                return -1
            }
        }
    }
    return len(higher)
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    input := scanner.Text()
​
    // 处理输入 [[2,1],[3,2]] => 2,1],[3,2
    input = input[2 : len(input)-2]
    arr := strings.Split(input, "],[")
​
    // 记录直接的师徒关系
    mp := make(map[int]map[int]bool)
    for _, s := range arr {
        tmp := strings.Split(s, ",")
        parent, _ := strconv.Atoi(tmp[0])
        child, _ := strconv.Atoi(tmp[1])
​
        if _, ok := mp[parent]; !ok {
            mp[parent] = make(map[int]bool)
        }
        if _, ok := mp[child]; !ok {
            mp[child] = make(map[int]bool)
        }
        mp[parent][child] = true
    }
​
    type Pair struct {
        Rank int
        Cnt  int
    }
    var ans []Pair
​
    for src := range mp {
        higher := make(map[int]bool)
        count := dfs(src, src, higher, mp)
        if count == -1 {
            fmt.Println(-1)
            return
        }
        ans = append(ans, Pair{src, count})
    }
​
    // 按照排名升序排序
    sort.Slice(ans, func(i, j int) bool {
        return ans[i].Rank < ans[j].Rank
    })
​
    // 格式化输出
    res := "["
    for _, p := range ans {
        res += fmt.Sprintf("%d,", p.Cnt)
    }
    res = res[:len(res)-1] + "]"
    fmt.Println(res)
}
